99	        return idempotency.execute(request.requestId(), "task.receipt", fingerprint, () -> {
100	            RolloutTask snapshot = taskRepository.findById(taskId)
101	                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
102	            ReleaseOrder lockedOrder = releaseRepository.findByIdForUpdate(snapshot.releaseId())
103	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
104	            RolloutTask task = taskRepository.findByIdForUpdate(taskId)
105	                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
