package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.Device;

/**
 * 设备视图。bootCount 为不可递减的非负启动计数；deviceVersion 为档案版本，维护成功一次加一。
 */
public record DeviceView(String deviceId, String model, String currentVersion, int bucketNo,
                         long bootCount, int deviceVersion) {

    public static DeviceView of(Device device) {
        return new DeviceView(device.deviceId(), device.model(), device.currentVersion(),
                device.bucketNo(), device.bootCount(), device.deviceVersion());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ReleaseOrder;
import com.example.starter.firmware.domain.RolloutTask;

/**
 * 投放任务视图。taskType/challenge/frozenBootCount 仅 BOOT_CHALLENGE 任务非空，
 * challenge 为领取时生成的合成挑战值，frozenBootCount 为领取时冻结的启动计数 b。
 */
public record TaskView(long taskId, long releaseId, String deviceId, String status,
                       String fromVersion, String toVersion, String taskType, String challenge,
                       Long frozenBootCount) {

    public static TaskView of(RolloutTask task, ReleaseOrder order) {
        return new TaskView(task.id(), task.releaseId(), task.deviceId(), task.status().name(),
                order.fromVersion(), order.toVersion(), task.taskType().name(), task.challenge(),
                task.frozenBootCount());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ReleaseOrder;

/**
 * 发布单视图。taskType 为任务类型：NORMAL 普通任务，BOOT_CHALLENGE 启动挑战任务。
 */
public record ReleaseView(long releaseId, int version, String model, String fromVersion, String toVersion,
                          int ratio, String status, String taskType, int sampleFloor,
                          int failureThresholdPercent, int monitorRound) {

    public static ReleaseView of(ReleaseOrder order) {
        return new ReleaseView(order.id(), order.version(), order.model(), order.fromVersion(),
                order.toVersion(), order.ratio(), order.status().name(), order.taskType().name(),
                order.sampleFloor(), order.failureThresholdPercent(), order.monitorRound());
    }
}

