        @Size(max = 64) String operator,
        @Size(max = 64) String challenge,
        Long bootCount) {

    /**
     * 兼容旧调用方：普通任务回执只需 requestId 与 result。
     */
    public ReceiptRequest(String requestId, ReceiptResult result) {
        this(requestId, result, null, null, null);
    }
}

